export function ProviderLogoIcon({ className, logo }: ProviderLogoProps) {
  const title = PROVIDER_LOGO_LABELS[logo];

  return (
    <span title={title} className={cn("inline-flex shrink-0 items-center justify-center", className)}>
      {logo === "alibaba" ? <AlibabaLogo className="size-full" /> : null}
      {logo === "bytedance" ? <ByteDanceLogo className="size-full" /> : null}
      {logo === "claude" ? <ClaudeLogo className="size-full" /> : null}
      {logo === "deepseek" ? <DeepSeekLogo className="size-full" /> : null}
      {logo === "gemini" ? <GeminiLogo className="size-full" /> : null}
      {logo === "google" ? <GoogleLogo className="size-full" /> : null}
      {logo === "kuaishou" ? <KuaishouLogo className="size-full" /> : null}
      {logo === "moonshot" ? <MoonshotLogo className="size-full" /> : null}
      {logo === "openai" ? <OpenAILogo className="size-full text-slate-950 dark:text-slate-100" /> : null}
      {logo === "vidu" ? <ViduLogo className="size-full text-slate-950 dark:text-slate-100" /> : null}
      {logo === "xai" ? <XAILogo className="size-full text-slate-950 dark:text-slate-100" /> : null}
      {logo === "zhipu" ? <ZhipuLogo className="size-full" /> : null}
    </span>
  );
}
